-- Synthetic, deterministic tests. No clocks are exposed by public mutation RPCs.
begin;
set local search_path=public,extensions;
select no_plan();
create function pg_temp.failure(statement text) returns text language plpgsql security invoker as $$
begin execute statement; return 'OK'; exception when others then return case when sqlstate='P0001' then sqlerrm else sqlstate end; end $$;
grant execute on function pg_temp.failure(text) to anon,authenticated,service_role;
create temp table api_cases(name text primary key, value jsonb);
grant all on api_cases to service_role;
grant all on api_cases to authenticated;
create function pg_temp.put(name text,value jsonb) returns void language sql as $$ insert into api_cases values(name,value) on conflict(name) do update set value=excluded.value $$;
create function pg_temp.get(name text) returns jsonb language sql stable as $$ select value from api_cases where api_cases.name=$1 $$;
create function pg_temp.sid(name text) returns uuid language sql stable as $$ select (pg_temp.get(name)#>>'{body,data,id}')::uuid $$;
create function pg_temp.start_body(client text,mode text default 'training',response text default 'typing') returns jsonb language sql immutable as $$
 select jsonb_build_object('client_session_id',client,'set_id','7dc73083-f0f1-46a4-ac65-7b7f42a6f9b1','set_version',1,'kind','diagnostic','practice_mode',mode,'response_mode',response,'session_size',20) $$;
create function pg_temp.import_body(client text,source text default 'guest_local',response text default 'typing') returns jsonb language sql stable as $$
 select jsonb_build_object('schema_version',1,'client_session_id',client,'source',source,'set_code','diagnostic-v1','set_version',1,'kind','diagnostic','practice_mode','training','response_mode',response,'started_at','2026-10-01T10:00:00Z','completed_at','2026-10-01T10:05:00Z','ended_early',false,
 'responses',(select jsonb_agg(jsonb_build_object('position',position,'word',word,'answer',case when response='paper' then '' else 'Synthetic answer.' end,'completed',true,'time_used_ms',1000) order by position) from public.wat_set_items)) $$;
grant execute on all functions in schema pg_temp to authenticated,service_role;
insert into auth.users(id,email,raw_user_meta_data) select ('00000000-0000-0000-0000-'||lpad(n::text,12,'0'))::uuid,'phase2-'||n||'@example.invalid','{"role":"admin"}' from generate_series(201,210) n;
select is((select count(*)::integer from profiles where role='candidate'),10,'Auth candidates ignore admin metadata');
select ok((select relrowsecurity and relforcerowsecurity from pg_class where oid='private.api_rate_windows'::regclass),'Private rate counters use forced RLS');
select ok(not has_table_privilege('authenticated','private.api_rate_windows','SELECT'),'Candidates cannot inspect rate counters');
select ok(not has_function_privilege('authenticated','public.qiyadat_mutate(uuid,text,jsonb,text,uuid,integer)','EXECUTE'),'Mutation RPC has no browser grant');
select ok(not has_function_privilege('anon','public.qiyadat_public_config(text)','EXECUTE'),'Public configuration SQL is server-only');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where n.nspname='private' and p.proname like 'api_%' and has_function_privilege('authenticated',p.oid,'EXECUTE')),'Private API helpers have no browser grants');
select ok(not exists(select 1 from pg_proc p join pg_namespace n on n.oid=p.pronamespace where (p.proname like 'qiyadat_%' or p.proname like 'api_%') and not 'search_path=""'=any(coalesce(p.proconfig,'{}'))),'All new API functions fix an empty search path');
set local role anon;
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','profile','{}')$q$),'42501','Anonymous cannot call trusted mutations');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000201","role":"authenticated"}',true);
select is(pg_temp.failure($q$select public.qiyadat_account_context('00000000-0000-0000-0000-000000000202')$q$),'42501','Candidate cannot query another account context');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','profile','{"role":"admin"}')$q$),'42501','Candidate cannot call service mutation with forged actor');
reset role;
set local role service_role;
select set_config('request.jwt.claims','{"role":"service_role"}',true);
select is(public.qiyadat_health(),true,'Trusted health checks database');
select is(jsonb_array_length(public.qiyadat_public_config('diagnostic')->'words'),20,'Published public config has 20 ordered words');
select is(public.qiyadat_public_config('diagnostic')->'rules','{"total_words":20,"seconds_per_word":15,"answer_grace_ms":2000,"answer_max_chars":280}'::jsonb,'Configuration constants match the contract');
select is(pg_temp.failure($q$select public.qiyadat_public_config('practice')$q$),'FEATURE_DISABLED','Unpublished practice configuration fails closed');
select is(public.qiyadat_account_context('00000000-0000-0000-0000-000000000201')#>>'{free_demo,status}','available','Fresh account has available authenticated demo');
select pg_temp.put('training',public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','start',pg_temp.start_body('train-a'),'phase2-start-key-0001'));
select is(pg_temp.get('training')->>'status','201','First free diagnostic starts with 201');
select is((select count(*)::integer from wat_responses where session_id=pg_temp.sid('training')),20,'Start atomically snapshots all positions');
select ok((select is_free_demo and expires_at=started_at+interval '30 minutes' from wat_sessions where id=pg_temp.sid('training')),'Start claims lifetime demo and 30-minute expiry');
select is(public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','start',pg_temp.start_body('train-a'),'phase2-start-key-0001'),pg_temp.get('training'),'Same idempotency request returns exact status/body');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','start',pg_temp.start_body('changed'),'phase2-start-key-0001')$q$),'IDEMPOTENCY_CONFLICT','Changed request cannot reuse key');
select pg_temp.put('resume',public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','start',pg_temp.start_body('different-device','simulation','paper'),'phase2-resume-key-0001'));
select is(pg_temp.get('resume')#>>'{body,data,id}',pg_temp.sid('training')::text,'Different device and mode resumes same free demo');
select is(pg_temp.get('resume')#>>'{body,data,resumed}','true','Free demo resume is explicit');
select is((select count(*)::integer from usage_reservations),0,'Start and resume consume no report quota');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000202','answer','{"answer":"cross-user"}',null,pg_temp.sid('training'),1)$q$),'NOT_FOUND','Cross-user answer reveals no session');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000202','finish','{"reason":"manual"}','cross-user-finish-key',pg_temp.sid('training'))$q$),'NOT_FOUND','Cross-user finish reveals no session');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','answer','{"answer":"x"}',null,pg_temp.sid('training'),0)$q$),'VALIDATION_ERROR','Position zero rejected');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','answer','{"answer":"x"}',null,pg_temp.sid('training'),21)$q$),'VALIDATION_ERROR','Position 21 rejected');
select is(public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','answer',jsonb_build_object('answer',repeat(chr(128512),280)),null,pg_temp.sid('training'),1)#>>'{body,data,saved}','true','280 Unicode code points accepted');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','answer',jsonb_build_object('answer',repeat(chr(128512),281)),null,pg_temp.sid('training'),1)$q$),'VALIDATION_ERROR','281 Unicode code points rejected');
select is(public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','answer',jsonb_build_object('answer',U&'e\0301'||E'\r\nNext'),null,pg_temp.sid('training'),1)#>>'{body,data,answer}',chr(233)||E'\nNext','Training replacement normalizes NFC and LF');
select is(public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','answer','{"answer":" \t"}',null,pg_temp.sid('training'),20)#>>'{body,data,answer}',E' \t','Whitespace blank wording preserved');
select is((select status::text from wat_responses where session_id=pg_temp.sid('training') and position=20),'blank','Whitespace-only answer counts as blank');
select pg_temp.put('finished',public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','finish','{"reason":"manual"}','phase2-finish-key-001',pg_temp.sid('training')));
select is(pg_temp.get('finished')#>>'{body,data,status}','finished','Typed finish reaches finished');
select is(pg_temp.get('finished')#>>'{body,data,ended_early}','true','Manual early finish identified');
select is(pg_temp.get('finished')#>>'{body,data,next_action}','generate_report','Typed next action matches contract');
select is((pg_temp.get('finished')#>'{body,data,statistics}')-'average_response_seconds'::text,'{"total_words":20,"completed_words":2,"answered_words":1,"blank_words":19}'::jsonb,'Statistics distinguish blanks and completion');
select ok((select bool_and(locked) from wat_responses where session_id=pg_temp.sid('training')),'Finish locks all typed positions');
select is(public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','finish','{"reason":"manual"}','phase2-finish-key-001',pg_temp.sid('training')),pg_temp.get('finished'),'Finish exact replay after state transition');
select is(public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','start',pg_temp.start_body('train-a'),'phase2-start-key-0001'),pg_temp.get('training'),'Original start replay unchanged after finish');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','finish','{"reason":"manual"}','phase2-finish-new-key',pg_temp.sid('training'))$q$),'SESSION_ALREADY_FINISHED','Different finish key cannot finish twice');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000201','start',pg_temp.start_body('second-free'),'second-free-key-0001')$q$),'DIAGNOSTIC_ALREADY_USED','Lifetime free demo cannot restart after completion');
select is((select count(*)::integer from processing_jobs),0,'Finish creates no OCR/feedback jobs');
select is((select count(*)::integer from usage_reservations),0,'Finish consumes no report quota');
-- Deterministic service-private clocks exercise exact timing, without sleeps.
select pg_temp.put('simulation',private.api_start_session('00000000-0000-0000-0000-000000000202',pg_temp.start_body('sim-a','simulation'),now()));
select is(pg_temp.failure($q$select private.api_save_answer('00000000-0000-0000-0000-000000000202',pg_temp.sid('simulation'),2,'{"answer":"early","client_saved_at":"2026-10-01T00:00:00Z"}',now()+interval '14.999999 seconds')$q$),'ANSWER_NOT_ACTIVE','Client timestamp cannot open a future window');
select is(private.api_save_answer('00000000-0000-0000-0000-000000000202',pg_temp.sid('simulation'),1,'{"answer":""}',now()+interval '15 seconds')#>>'{body,data,locked}','true','Exact deadline accepts and locks blank answer');
select is(private.api_save_answer('00000000-0000-0000-0000-000000000202',pg_temp.sid('simulation'),2,'{"answer":"grace"}',now()+interval '32 seconds')#>>'{body,data,saved}','true','Exact 2000ms grace boundary accepted');
select is(pg_temp.failure($q$select private.api_save_answer('00000000-0000-0000-0000-000000000202',pg_temp.sid('simulation'),3,'{"answer":"late"}',now()+interval '47.000001 seconds')$q$),'SESSION_LATE_ANSWER','One microsecond after grace rejected');
select is(pg_temp.failure($q$select private.api_save_answer('00000000-0000-0000-0000-000000000202',pg_temp.sid('simulation'),1,'{"answer":"replace"}',now()+interval '15 seconds')$q$),'ANSWER_ALREADY_LOCKED','Accepted simulation answer immutable');
select is(private.api_save_answer('00000000-0000-0000-0000-000000000202',pg_temp.sid('simulation'),20,'{"answer":"last"}',now()+interval '300 seconds')#>>'{body,data,position}','20','Position 20 exact deadline accepted');
select pg_temp.put('sim_finish',private.api_finish_session('00000000-0000-0000-0000-000000000202',pg_temp.sid('simulation'),'{"reason":"natural"}',now()+interval '301 seconds'));
select is(pg_temp.get('sim_finish')#>>'{body,data,statistics,completed_words}','20','Natural finish fills expired windows');
select is(pg_temp.get('sim_finish')#>>'{body,data,statistics,blank_words}','18','Natural finish counts missing words as blanks');
select is(pg_temp.get('sim_finish')#>>'{body,data,ended_early}','false','Complete simulation is not early');
select pg_temp.put('paper',private.api_start_session('00000000-0000-0000-0000-000000000203',pg_temp.start_body('paper-a','training','paper'),now()));
select is(pg_temp.failure($q$select private.api_save_answer('00000000-0000-0000-0000-000000000203',pg_temp.sid('paper'),1,'{"answer":"x"}',now())$q$),'SESSION_STATE_CONFLICT','Paper cannot use typed answer API');
select pg_temp.put('paper_finish',private.api_finish_session('00000000-0000-0000-0000-000000000203',pg_temp.sid('paper'),'{"reason":"natural"}',now()));
select is(pg_temp.get('paper_finish')#>>'{body,data,status}','awaiting_upload','Paper finish awaits future upload');
select is(pg_temp.get('paper_finish')#>>'{body,data,next_action}','upload_paper_pages','Paper next action matches contract');
select ok((select bool_and(not locked) from wat_responses where session_id=pg_temp.sid('paper')),'Paper placeholders remain writable by future trusted OCR');
select pg_temp.put('expired',private.api_start_session('00000000-0000-0000-0000-000000000204',pg_temp.start_body('expired'),now()));
select is(pg_temp.failure($q$select private.api_save_answer('00000000-0000-0000-0000-000000000204',pg_temp.sid('expired'),1,'{"answer":"expired"}',now()+interval '30 minutes')$q$),'SESSION_EXPIRED','Exact write expiry rejects answer');
select is(pg_temp.failure($q$select private.api_finish_session('00000000-0000-0000-0000-000000000204',pg_temp.sid('expired'),'{"reason":"manual"}',now()+interval '30 minutes')$q$),'SESSION_EXPIRED','Exact write expiry rejects finish');
select is(pg_temp.failure($q$select private.api_start_session('00000000-0000-0000-0000-000000000204',pg_temp.start_body('new-expired'),now()+interval '30 minutes')$q$),'DIAGNOSTIC_ALREADY_USED','Expired free claim cannot be replaced');
-- Import is history-only for free accounts; it never claims the authenticated demo.
select pg_temp.put('guest',public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','import',pg_temp.import_body('guest-a'),'phase2-import-key-001'));
select is(pg_temp.get('guest')#>>'{body,data,timing_trust}','client_reported','Guest timing always client-reported');
select is(pg_temp.get('guest')#>>'{body,data,eligible_for_feedback}','false','Free guest import is not entitled feedback');
select is(public.qiyadat_account_context('00000000-0000-0000-0000-000000000205')#>>'{free_demo,status}','available','Import never claims server diagnostic demo');
select is(public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','import',pg_temp.import_body('guest-a'),'phase2-import-key-001'),pg_temp.get('guest'),'Import same key exact replay');
select is(public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','import',pg_temp.import_body('guest-a'),'phase2-import-key-002')->>'status','200','Client session id deduplicates across new keys');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','import',jsonb_set(pg_temp.import_body('guest-b'),'{responses,0,word}','"WRONG"'),'bad-word-key-0001')$q$),'CONFIG_VERSION_MISMATCH','Import rejects mismatched immutable word');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','import',jsonb_set(pg_temp.import_body('guest-b'),'{responses,1,position}','1'),'bad-position-key-01')$q$),'VALIDATION_ERROR','Import rejects duplicate positions');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','import',jsonb_set(pg_temp.import_body('guest-b'),'{responses}',(pg_temp.import_body('guest-b')->'responses')-0),'missing-pos-key-001')$q$),'VALIDATION_ERROR','Import rejects missing position');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','import',jsonb_set(pg_temp.import_body('guest-b'),'{completed_at}','"2026-09-01T00:00:00Z"'),'bad-date-key-0001')$q$),'VALIDATION_ERROR','Import completion cannot precede start');
select pg_temp.put('legacy',public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','import',pg_temp.import_body('legacy-a','legacy_local_storage'),'legacy-import-key-01'));
select is((select source::text from wat_responses where session_id=pg_temp.sid('legacy') limit 1),'legacy_typed','Legacy response source retained');
insert into entitlements(user_id,type,starts_at,expires_at) values('00000000-0000-0000-0000-000000000206','founding_30d',now()-interval '1 day',now()+interval '29 days');
select pg_temp.put('paper_import',public.qiyadat_mutate('00000000-0000-0000-0000-000000000206','import',pg_temp.import_body('paper-import','guest_local','paper'),'paper-import-key-01'));
select is(pg_temp.get('paper_import')#>>'{body,data,eligible_for_feedback}','false','Paid paper import without text stays activity-only');
select pg_temp.put('paid',public.qiyadat_mutate('00000000-0000-0000-0000-000000000206','start',pg_temp.start_body('paid-a'),'paid-start-key-0001'));
select ok((select not is_free_demo from wat_sessions where id=pg_temp.sid('paid')),'Paid session does not consume free demo');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000206','start',pg_temp.start_body('paid-b'),'paid-start-key-0002')$q$),'SESSION_STATE_CONFLICT','Paid account still has only one active server session');
-- Account writes are strictly atomic, safe-field only, and consent-version bound.
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','profile','{"role":"admin"}')$q$),'VALIDATION_ERROR','Profile role change rejected');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','profile','{"entitlement":"founding_30d"}')$q$),'VALIDATION_ERROR','Profile entitlement change rejected');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','profile','{"display_name":"Should roll back","timezone":"Mars/Olympus"}')$q$),'VALIDATION_ERROR','Invalid timezone rolls back whole patch');
select isnt((select display_name from profiles where id='00000000-0000-0000-0000-000000000205'),'Should roll back','Failed profile patch is atomic');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','profile','{"display_name":"   "}')$q$),'VALIDATION_ERROR','Empty trimmed display name rejected');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','profile','{"accept_ai_processing_terms_version":"future"}')$q$),'VALIDATION_ERROR','Arbitrary consent version rejected');
select lives_ok($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000205','profile',jsonb_build_object('display_name',' Candidate ','timezone','Asia/Karachi','accept_ai_processing_terms_version',(select value#>>'{}' from app_settings where key='ai_processing_terms_version')))$q$,'Safe profile and current consent accepted');
select is((select display_name from profiles where id='00000000-0000-0000-0000-000000000205'),'Candidate','Display name trimmed');
select is(public.qiyadat_account_context('00000000-0000-0000-0000-000000000205')#>>'{ai_processing_consent,accepted}','true','Current consent reflected in account');
select is(public.qiyadat_admin_check('00000000-0000-0000-0000-000000000205'),false,'Metadata does not confer protected admin membership');
select is(pg_temp.failure($q$select public.qiyadat_mutate('00000000-0000-0000-0000-000000000207','start',jsonb_set(pg_temp.start_body('stale'),'{set_version}','2'),'stale-config-key-01')$q$),'CONFIG_VERSION_MISMATCH','Stale configuration rejected');
select is((select count(*)::integer from api_idempotency_keys where idempotency_key='stale-config-key-01'),0,'Failed mutation rolls back idempotency reservation');
select ok((select bool_and(expires_at>=created_at+interval '24 hours') from api_idempotency_keys),'Idempotency retained for at least 24 hours');
update app_settings set value='true' where key='beta_open';
select is(public.qiyadat_account_context('00000000-0000-0000-0000-000000000208')#>>'{entitlement,type}','beta','Beta issued on first authenticated use when enabled');
select ok(public.qiyadat_account_context('00000000-0000-0000-0000-000000000208') is not null,'Repeated beta account read succeeds');
select is((select count(*)::integer from entitlements where user_id='00000000-0000-0000-0000-000000000208'),1,'Beta membership cannot duplicate');
update app_settings set value='false' where key='beta_open';
select ok(not private.api_has_access('00000000-0000-0000-0000-000000000208',now()),'Closed beta no longer grants session access');
reset role;
set local role authenticated;
select set_config('request.jwt.claims','{"sub":"00000000-0000-0000-0000-000000000205","role":"authenticated"}',true);
select is(jsonb_array_length(public.qiyadat_history()->'items'),2,'History contains only own imports');
select is(jsonb_array_length(public.qiyadat_history('{"practice_mode":"simulation"}')->'items'),0,'History filters mode');
select is(jsonb_array_length(public.qiyadat_history('{"status":"finished"}')->'items'),2,'History filters status');
select pg_temp.put('history',public.qiyadat_history('{}',null,1));
select is(pg_temp.get('history')->>'has_more','true','History pagination detects more rows');
select isnt((pg_temp.get('history')#>>'{items,0,id}'),public.qiyadat_history('{}',pg_temp.get('history')->'next',1)#>>'{items,0,id}','Cursor advances even with tied timestamps');
select is(public.qiyadat_history('{}',pg_temp.get('history')->'next',1)->>'has_more','false','Last page has no next cursor');
select ok(not ((public.qiyadat_history()->'items'->0) ? 'responses'),'History never includes answer bodies');
select is(pg_temp.failure($q$select public.qiyadat_history('{}',null,101)$q$),'VALIDATION_ERROR','History limit above 100 rejected');
select is(pg_temp.failure($q$select public.qiyadat_history('{}','{"at":"bad","id":"bad"}',20)$q$),'VALIDATION_ERROR','Malformed cursor rejected safely');
select is((select count(*)::integer from wat_sessions where id=pg_temp.sid('training')),0,'Candidate reads cannot see another user session');
reset role;
select * from finish();
rollback;
